from pwn import *
import numpy as np
import matplotlib.pyplot as plt
import base64

freq = 24000

def point(tab):
    for _ in range(freq // 1000):
        tab.append(1)
    for _ in range(freq // 1000):
        tab.append(0)

def dash(tab):
    for _ in range(5* freq // 1000):
        tab.append(1)
    for _ in range(freq // 1000):
        tab.append(0)

def next_letter(tab):
    for _ in range(4 * freq // 1000):
        tab.append(0)

def next_word(tab):
    for _ in range(19 * freq // 1000):
        tab.append(0)

def sentence_to_morse(sentence):
    tab = []
    for c in sentence:
        if c == '.':
            point(tab)
        elif c == '-':
            dash(tab)
        elif c == ' ':
            next_letter(tab)
        else:
            next_word(tab)
    return tab

