def find_d(N,e,c,d0,d0bits=512):
    for k in range(1,e):
        # Approximate d using N instead of phi
        d = ((k * N + 1) // e)

        # Replace the LSB of d by the known value
        d ^= (d % (1 << d0bits))
        d ^= d0

        # Brute force the remaining 4 bits
        for i1 in range(2):
            for i2 in range(2):
                for i3 in range(2):
                    for i4 in range(2):
                        d ^= (i1 << 512)
                        d ^= (i2 << 513)
                        d ^= (i3 << 514)
                        d ^= (i4 << 515)

                        if pow(pow(2,e,N),d,N) == 2:
                            return d

import string
import random

N = 8

def encode(pwd):
    def F(tmp):
        if tmp % 2:
            return (tmp % 26) + ord('A')
        else:
            r = tmp % 16
            if r < 10:
                return ord('0') + r
            else:
                return r - 10 + ord('A')

    a, res = 0, []
    for i in range(len(pwd)):
        P, c, S = pwd[:i], pwd[i], pwd[i+1:]
        S1, S2, T = sum(P), sum(S), sum(pwd)
        a = F((a + c) * i + T)
        res.append(a)

    return bytes(res)

def get_random_string(length):
    return ''.join(random.choice(string.ascii_letters) for _ in range(length)).encode()

