def egcd(a,b):
    # Returns (g,u,v) such that au+bv = g = gcd(a,b)
    if b == 0:
        return (a, 1, 0)
    g,u,v = egcd(b, a%b)
    return (g,v,u-(a//b)*v)

def modinv(a,n):
    g,u,_ = egcd(a,n)
    return u % n

